import{_ as t,o as a,c as n,ag as r}from"./chunks/framework.BuUvxvtQ.js";const p=JSON.parse('{"title":"Contributing to Sky Style","description":"","frontmatter":{},"headers":[],"relativePath":"development/index.md","filePath":"development/index.md"}'),o={name:"development/index.md"};function i(s,e,d,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="contributing-to-sky-style" tabindex="-1">Contributing to Sky Style <a class="header-anchor" href="#contributing-to-sky-style" aria-label="Permalink to &quot;Contributing to Sky Style&quot;">​</a></h1><p>The web app and public API run in the same Next.js application. The documentation site is a separate VitePress build. Start with the <a href="https://github.com/COOLmanYT/skystyle/blob/main/SETUP.md" target="_blank" rel="noreferrer">repository setup guide</a> to configure a development environment.</p><h2 id="choose-a-guide" tabindex="-1">Choose a guide <a class="header-anchor" href="#choose-a-guide" aria-label="Permalink to &quot;Choose a guide&quot;">​</a></h2><ul><li><a href="./architecture.html">Architecture</a>: where pages, API routes, provider adapters and data access live.</li><li><a href="./testing.html">Testing</a>: run checks and write useful regression tests.</li><li><a href="./../web-app/dev-center.html">Dev Center</a>: use the restricted account, support and monitoring tools.</li><li><a href="./../api/">API reference</a>: build an integration with an API key.</li></ul><h2 id="run-locally" tabindex="-1">Run locally <a class="header-anchor" href="#run-locally" aria-label="Permalink to &quot;Run locally&quot;">​</a></h2><p>From the repository root, install dependencies with <code>npm ci</code>. Configure <code>apps/web/.env.local</code> using <code>.env.example</code>, then run <code>npm run dev</code>. Set local origin variables and registered GitHub/Google callbacks to the port you use.</p><p>The docs need no product credentials: run <code>npm run docs:dev</code> and open the URL printed by VitePress.</p><h2 id="make-a-change" tabindex="-1">Make a change <a class="header-anchor" href="#make-a-change" aria-label="Permalink to &quot;Make a change&quot;">​</a></h2><p>Use the existing code near your change as a starting point. Keep server credentials on the server, validate input, and check authentication and ownership before accessing account data. Update the relevant user guide or API reference when behavior changes.</p><p>Run the checks in <a href="./testing.html">Testing</a> before submitting a pull request. Documentation builds reject missing internal page links. Generated documentation output is built during deployment and is not maintained as source.</p><h2 id="hosting-and-background-jobs" tabindex="-1">Hosting and background jobs <a class="header-anchor" href="#hosting-and-background-jobs" aria-label="Permalink to &quot;Hosting and background jobs&quot;">​</a></h2><p>The web app is hosted at <a href="https://skystyle.app" target="_blank" rel="noreferrer">skystyle.app</a>; the docs are hosted at <a href="https://docs.skystyle.app" target="_blank" rel="noreferrer">docs.skystyle.app</a>. Deployments use the corresponding app workspace.</p><p>Automatic recommendations use Supabase Cron to call the authenticated web worker. Running the app does not install a recurring job. Keep scheduler credentials in server-side secret storage, use the worker&#39;s required authorization, and review deployment-specific setup before scheduling requests.</p>',13)])])}const g=t(o,[["render",i]]);export{p as __pageData,g as default};
